{
  "name": "mundo-de-blocos",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Um jogo de mundo aberto em blocos, em português brasileiro.",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
}

/* ============================================================
   MUNDO DE BLOCOS — estilo pixel/arcade em português brasileiro
   ============================================================ */

@font-face {
  font-family: 'Silkscreen';
  src: url('./assets/fonts/silkscreen-400.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Silkscreen';
  src: url('./assets/fonts/silkscreen-700.woff2') format('woff2');
  font-weight: 700;
  font-display: swap;
}
@font-face {
  font-family: 'VT323';
  src: url('./assets/fonts/vt323.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}

:root {
  --bg-deep: #070d17;
  --bg: #0b1422;
  --panel: #142033;
  --panel-2: #1a2a42;
  --line: #35506f;
  --line-dark: #05090f;
  --text: #eef4fc;
  --muted: #9fb3cb;
  --green: #7bc043;
  --green-dark: #3f7a22;
  --green-deep: #22470f;
  --gold: #f2c14e;
  --orange: #e08a4b;
  --water: #1d5fa8;
  --shadow: 0 22px 60px rgba(0, 0, 0, 0.55);
  --font-pixel: 'Silkscreen', 'Courier New', monospace;
  --font-body: 'VT323', 'Courier New', monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg-deep);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 20px;
  -webkit-font-smoothing: none;
  text-rendering: optimizeSpeed;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

body {
  position: fixed;
  inset: 0;
}

button {
  font-family: var(--font-pixel);
  color: inherit;
  cursor: pointer;
  border: 0;
  background: none;
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid var(--gold);
  outline-offset: 2px;
}

img {
  image-rendering: pixelated;
}

canvas#game {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
}

.hidden {
  display: none !important;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background: radial-gradient(ellipse at center, transparent 52%, rgba(2, 6, 12, 0.4) 100%);
  transition: opacity 0.4s ease;
}

#water-tint {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  background: radial-gradient(ellipse at center, rgba(28, 92, 170, 0.28), rgba(9, 40, 88, 0.62));
  opacity: 0;
  transition: opacity 0.25s ease;
}

/* ============================ HUD ============================ */

#hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: calc(10px + var(--safe-top)) calc(12px + var(--safe-right)) calc(10px + var(--safe-bottom)) calc(12px + var(--safe-left));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex-wrap: wrap;
}

.hud-spacer {
  flex: 1;
}

.hud-chip {
  font-family: var(--font-pixel);
  font-size: 10px;
  line-height: 1.4;
  letter-spacing: 0.04em;
  color: #e9f2ff;
  background: rgba(7, 13, 24, 0.62);
  border: 2px solid rgba(3, 7, 13, 0.75);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  padding: 7px 10px;
  border-radius: 3px;
  backdrop-filter: blur(4px);
  white-space: nowrap;
}

.hud-coords {
  color: #c5d6ea;
}

.hud-clock {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

#clock-icon {
  font-size: 13px;
  filter: drop-shadow(0 0 6px rgba(255, 213, 112, 0.7));
}

.hud-top .icon-btn {
  pointer-events: auto;
  width: 34px;
  height: 34px;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  padding: 8px;
  border-radius: 4px;
  background: rgba(10, 18, 30, 0.72);
  border: 2px solid rgba(0, 0, 0, 0.6);
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.09), inset 0 -2px 0 rgba(0, 0, 0, 0.35);
  color: #dce8f7;
  backdrop-filter: blur(4px);
  transition: background 0.15s ease, transform 0.1s ease;
}

.icon-btn:hover {
  background: rgba(32, 54, 82, 0.9);
}

.icon-btn:active {
  transform: translateY(1px);
}

.icon-btn svg {
  width: 100%;
  height: 100%;
  fill: currentColor;
}

.hud-center {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

#crosshair {
  position: relative;
  width: 22px;
  height: 22px;
  mix-blend-mode: difference;
  opacity: 0.95;
}

#crosshair::before,
#crosshair::after {
  content: '';
  position: absolute;
  background: #fff;
  box-shadow: 0 0 1px rgba(0, 0, 0, 0.8);
}

#crosshair::before {
  left: 50%;
  top: 0;
  width: 2px;
  height: 22px;
  transform: translateX(-50%);
}

#crosshair::after {
  top: 50%;
  left: 0;
  width: 22px;
  height: 2px;
  transform: translateY(-50%);
}

#target-name {
  font-family: var(--font-pixel);
  font-size: 10px;
  letter-spacing: 0.05em;
  color: #f7fbff;
  background: rgba(6, 11, 20, 0.72);
  border: 2px solid rgba(0, 0, 0, 0.55);
  padding: 5px 9px;
  border-radius: 3px;
  text-shadow: 0 1px 0 #000;
  white-space: nowrap;
}

#toast-area {
  position: absolute;
  top: calc(64px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: min(92vw, 460px);
  pointer-events: none;
}

.toast {
  font-family: var(--font-pixel);
  font-size: 11px;
  line-height: 1.5;
  text-align: center;
  color: #f5faff;
  background: rgba(10, 19, 33, 0.88);
  border: 2px solid rgba(0, 0, 0, 0.6);
  border-left: 4px solid var(--green);
  padding: 9px 14px;
  border-radius: 3px;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.4);
  animation: toastIn 0.22s ease both;
  backdrop-filter: blur(6px);
}

.toast.out {
  animation: toastOut 0.28s ease both;
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }
}

.hud-bottom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
}

#slot-name {
  font-family: var(--font-pixel);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: #fff;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.8);
}

#hotbar {
  display: flex;
  gap: 3px;
  padding: 4px;
  background: rgba(5, 10, 18, 0.55);
  border: 2px solid rgba(0, 0, 0, 0.5);
  border-radius: 3px;
  pointer-events: auto;
  backdrop-filter: blur(5px);
}

.slot {
  position: relative;
  width: clamp(34px, 8vw, 56px);
  height: clamp(34px, 8vw, 56px);
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(24, 38, 57, 0.82);
  border: 2px solid #060b12;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.09), inset 0 -3px 0 rgba(0, 0, 0, 0.3);
  border-radius: 2px;
  transition: transform 0.1s ease, box-shadow 0.12s ease, background 0.12s ease;
}

.slot img {
  width: 82%;
  height: 82%;
  object-fit: contain;
  filter: drop-shadow(0 2px 1px rgba(0, 0, 0, 0.45));
  pointer-events: none;
}

.slot .num {
  position: absolute;
  top: 1px;
  left: 3px;
  font-family: var(--font-pixel);
  font-size: 8px;
  color: rgba(255, 255, 255, 0.6);
  text-shadow: 0 1px 0 #000;
}

.slot.selected {
  background: rgba(66, 96, 128, 0.92);
  box-shadow: inset 0 0 0 2px #f8fbff, 0 0 0 2px rgba(0, 0, 0, 0.5), 0 6px 14px rgba(0, 0, 0, 0.35);
  transform: translateY(-4px);
}

#hud-hint {
  font-size: 16px;
  color: rgba(228, 239, 252, 0.82);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.9);
  letter-spacing: 0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 96vw;
}

#hud-hint b {
  color: #d7f0b8;
  font-weight: 400;
}

.fps {
  position: fixed;
  top: calc(10px + var(--safe-top));
  left: calc(12px + var(--safe-left));
  z-index: 12;
  font-family: var(--font-pixel);
  font-size: 9px;
  color: #a9f08a;
  background: rgba(0, 0, 0, 0.45);
  padding: 4px 6px;
  pointer-events: none;
}

body.is-touch .only-desktop {
  display: none !important;
}

.only-touch {
  display: none;
}

body.is-touch .only-touch {
  display: inline-flex;
}

/* =========================== MENU =========================== */

.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(18px + var(--safe-top)) calc(22px + var(--safe-right)) calc(18px + var(--safe-bottom))
    calc(22px + var(--safe-left));
}

.menu-screen {
  z-index: 20;
  flex-direction: column;
  justify-content: space-between;
  background:
    radial-gradient(ellipse 70% 80% at 20% 42%, rgba(7, 15, 28, 0.18), transparent 70%),
    linear-gradient(100deg, rgba(4, 9, 17, 0.32) 0%, rgba(4, 9, 17, 0.12) 45%, rgba(4, 9, 17, 0.78) 100%),
    linear-gradient(0deg, rgba(4, 9, 17, 0.85) 0%, transparent 34%, rgba(4, 9, 17, 0.55) 100%);
  animation: menuFade 0.5s ease both;
}

@keyframes menuFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.menu-topbar {
  width: 100%;
  max-width: 1200px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand-mini {
  font-family: var(--font-pixel);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: #dfeaf8;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.6);
}

.brand-dot {
  width: 10px;
  height: 10px;
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(123, 192, 67, 0.22), inset 0 0 0 2px rgba(0, 0, 0, 0.35);
}

.menu-top-right {
  display: flex;
  gap: 8px;
}

.menu-grid {
  width: 100%;
  max-width: 1200px;
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(320px, 0.78fr);
  align-items: center;
  gap: clamp(24px, 5vw, 72px);
  padding: 10px 0;
}

.menu-hero {
  position: relative;
  max-width: 620px;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-pixel);
  font-size: 9px;
  letter-spacing: 0.16em;
  color: #c7f0a1;
  background: rgba(9, 20, 12, 0.68);
  border: 2px solid rgba(123, 192, 67, 0.42);
  padding: 7px 10px;
  border-radius: 2px;
  margin-bottom: 18px;
  backdrop-filter: blur(4px);
}

.logo-block {
  display: block;
  width: clamp(70px, 10vw, 118px);
  height: auto;
  margin-bottom: 18px;
  filter: drop-shadow(0 16px 22px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 26px rgba(123, 192, 67, 0.18));
  animation: floatBlock 5.5s ease-in-out infinite;
  image-rendering: pixelated;
}

@keyframes floatBlock {
  0%,
  100% {
    transform: translateY(0) rotate(-3deg);
  }
  50% {
    transform: translateY(-10px) rotate(3deg);
  }
}

.logo-title {
  font-family: var(--font-pixel);
  font-weight: 700;
  font-size: clamp(38px, 6.8vw, 82px);
  line-height: 0.96;
  letter-spacing: 0.01em;
  margin: 0 0 22px;
  color: #f4f8ff;
  text-shadow: 0 3px 0 #48566b, 0 6px 0 #26303f, 0 10px 24px rgba(0, 0, 0, 0.65);
}

.logo-title span {
  color: var(--green);
  text-shadow: 0 3px 0 #2f5e1a, 0 6px 0 #1a350d, 0 10px 26px rgba(0, 0, 0, 0.7);
}

.tagline {
  font-size: clamp(19px, 2.2vw, 24px);
  line-height: 1.25;
  color: #d5e2f1;
  max-width: 520px;
  margin: 0 0 20px;
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.7);
}

.hero-features {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 18px;
  padding: 0;
  margin: 0 0 24px;
  max-width: 520px;
}

.hero-features li {
  font-size: 18px;
  color: #c3d3e6;
  display: flex;
  align-items: center;
  gap: 8px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
}

.hero-features span {
  color: var(--green);
  font-size: 11px;
}

.hero-world {
  display: flex;
  gap: 28px;
  padding-top: 18px;
  border-top: 2px solid rgba(173, 200, 230, 0.16);
  max-width: 520px;
}

.hero-world small {
  display: block;
  font-family: var(--font-pixel);
  font-size: 8px;
  letter-spacing: 0.14em;
  color: #7f95ad;
  margin-bottom: 5px;
}

.hero-world b {
  display: block;
  font-weight: 400;
  font-size: 19px;
  color: #e6effa;
  max-width: 260px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.menu-panel {
  width: 100%;
  background: linear-gradient(180deg, rgba(24, 38, 58, 0.96), rgba(14, 24, 39, 0.97));
  border: 3px solid #05090f;
  border-radius: 4px;
  box-shadow: inset 0 3px 0 rgba(255, 255, 255, 0.08), inset 0 0 0 1px rgba(107, 143, 184, 0.25), var(--shadow);
  padding: 26px;
  backdrop-filter: blur(10px);
}

.panel-head {
  margin-bottom: 18px;
}

.panel-head.center {
  text-align: center;
}

.panel-kicker {
  display: block;
  font-family: var(--font-pixel);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--gold);
  margin-bottom: 8px;
}

.panel-head h2 {
  font-family: var(--font-pixel);
  font-weight: 400;
  font-size: clamp(20px, 2.2vw, 25px);
  margin: 0;
  color: #f2f7ff;
  line-height: 1.25;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.5);
}

.menu-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  text-align: left;
  width: 100%;
  padding: 13px 16px;
  background: linear-gradient(180deg, #334762, #27384f);
  border: 3px solid #05090f;
  border-radius: 3px;
